INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 22, 'theory', 'Quiz: replication');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 22, 0, 'A user changed their name and immediately opened their profile, but sees the old name. What happened and how is it treated?', '["The leader lost the write; treated with a full restart", "The read hit a lagging replica; treated by reading from the leader after a write or with an LSN token", "The browser cache; treated by clearing cookies", "A deadlock; treated by retrying the transaction"]', 1, 'This is a violation of the read-your-writes guarantee. You read from the leader for fresh changes, or only from replicas that have already applied the client''s write position.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 22, 1, 'What is split-brain and how is it fought?', '["Loss of the log; fought with a backup", "A split of an index; fought with a rebuild", "Two nodes consider themselves leaders at the same time; fought with epoch numbers, fencing and consensus", "Clock desynchronization; fought with NTP"]', 2, 'A write carrying the epoch number of a past leader is rejected by the storage; electing the leader by majority (Raft) rules out two leaders in one epoch.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 22, 2, 'With N = 3, a write is confirmed by two replicas and a read queries two. Does this guarantee a fresh read?', '["No: you need to query all three", "No: quorums do not work without a leader", "Yes, but only with synchronized clocks", "Yes: W + R = 4 > N = 3, the read will overlap with a replica that has the latest write"]', 3, 'The intersection of sets guarantees that among the queried replicas there is at least one fresh one; the client picks the value with the highest version.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 22, 3, 'Two versions of a record have vectors {A:3, B:1} and {A:2, B:2}. What does this mean?', '["The first is newer", "The versions are concurrent — a real conflict occurred, they must be merged", "The second is newer", "The versions are equal"]', 1, 'Neither vector is smaller than the other in all components: the changes arose independently. One is newer only when all of its counters are no smaller.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 22, 4, 'Why does replication not replace backups?', '["Because replicas are slower", "Because replicas store only indexes", "Because accidental deletion or corruption of data is instantly replicated to all copies", "Because a backup is encrypted"]', 2, 'You need a copy of a past point in time with a change log. To protect against human error, a replica with a deliberate delay is sometimes kept.');
